import React from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import { Navigation, Pagination, Autoplay } from "swiper/modules";

import "swiper/css";
import "swiper/css/navigation";
import "swiper/css/pagination";

import "./projectGallery.css";

const projects = [
  {
    id: 1,
    image: "/interior.jpg",
    title: "Luxury Living Room",
    link: "/projects/luxury-living-room",
  },
  {
    id: 2,
    image: "/architecture_detailss.png",
    title: "Modern Bedroom",
    link: "/projects/modern-bedroom",
  },
  {
    id: 3,
    image: "/arch.jpg",
    title: "Elegant Kitchen",
    link: "/projects/elegant-kitchen",
  },
  {
    id: 4,
    image: "/about_1.jpg",
    title: "Workspace Design",
    link: "/projects/workspace-design",
  },
];

const ProjectCarousel = () => {
  return (
    <section className="portfolio-section">
      <div className="section-heading">
        <h2>Our Projects</h2>
        <p>Transforming Spaces with Elegant Interior Design</p>
      </div>

      <Swiper
        modules={[Navigation, Pagination, Autoplay]}
        navigation
        pagination={{ clickable: true }}
        autoplay={{
          delay: 3500,
          disableOnInteraction: false,
        }}
        loop
        spaceBetween={30}
        slidesPerView={1}
        breakpoints={{
          768: {
            slidesPerView: 2,
          },
          1024: {
            slidesPerView: 3,
          },
        }}
      >
        {projects.map((project) => (
          <SwiperSlide key={project.id}>
            <a href={project.link} className="project-card">
              <img src={project.image} alt={project.title} />
              <div className="overlay">
                <h3>{project.title}</h3>
              </div>
            </a>
          </SwiperSlide>
        ))}
      </Swiper>
    </section>
  );
};

export default ProjectCarousel;
